#include <iostream>
#include <string>
#include <memory>
#include <vector>
#include <cmath>
#include <iomanip>

// Abstract Base Class
class GeometricObject {
private:
    std::string color;
    bool filled;

public:
    GeometricObject(const std::string& col = "white", bool fill = false)
        : color(col), filled(fill) {}

    virtual ~GeometricObject() = default; // Essential virtual destructor

    std::string getColor() const { return color; }
    void setColor(const std::string& col) { color = col; }
    bool isFilled() const { return filled; }
    void setFilled(bool fill) { filled = fill; }

    // Pure virtual functions make this class abstract
    virtual double getArea() const = 0;
    virtual double getPerimeter() const = 0;
    virtual std::string toString() const = 0;
};

class Triangle : public GeometricObject {
private:
    double side1{1.0};
    double side2{1.0};
    double side3{1.0};

public:
    Triangle() = default;
    Triangle(double s1, double s2, double s3, const std::string& col = "white", bool fill = false)
        : GeometricObject(col, fill), side1(s1), side2(s2), side3(s3) {}

    double getSide1() const { return side1; }
    double getSide2() const { return side2; }
    double getSide3() const { return side3; }

    double getPerimeter() const override {
        return side1 + side2 + side3;
    }

    double getArea() const override {
        double s = getPerimeter() / 2.0;
        return std::sqrt(s * (s - side1) * (s - side2) * (s - side3));
    }

    std::string toString() const override {
        return "Triangle: side1=" + std::to_string(side1) + ", side2=" + 
               std::to_string(side2) + ", side3=" + std::to_string(side3);
    }
};

int main() {
    // Creating an object polymorphically
    std::unique_ptr<GeometricObject> shape = 
        std::make_unique<Triangle>(3.0, 4.0, 5.0, "blue", true);

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Shape color: " << shape->getColor() << "\n";
    std::cout << "Filled: " << (shape->isFilled() ? "true" : "false") << "\n";
    std::cout << "Area: " << shape->getArea() << "\n";
    std::cout << "Perimeter: " << shape->getPerimeter() << "\n";

    // Safe downcasting using dynamic_cast
    Triangle* triPtr = dynamic_cast<Triangle*>(shape.get());
    if (triPtr != nullptr) {
        std::cout << "dynamic_cast successful: side1 is " << triPtr->getSide1() << "\n";
    } else {
        std::cout << "dynamic_cast failed.\n";
    }

    return 0;
}
